// Generated by emitters/n8n.ts from the Nifty operations catalog (0.1.0, spec 0.137.0). Do not edit by hand.
import { NodeConnectionTypes } from 'n8n-workflow';
import type { IDataObject, IHttpRequestMethods, ILoadOptionsFunctions, INodeExecutionData, INodePropertyOptions, INodeType, INodeTypeDescription, IPollFunctions } from 'n8n-workflow';

const BASE_URL = 'https://openapi.niftypm.com/api/v3';
// The credential the `authentication` option picks.
function credentialOf(context: IPollFunctions | ILoadOptionsFunctions): string {
	return context.getNodeParameter('authentication', 'apiKey') === 'oAuth2' ? 'niftyOAuth2Api' : 'niftyApi';
}

// Ids remembered for the current event and filter so that a task is delivered once; bounded, newest first. A poll reads one page, so at most
// one page of new items per poll is seen (the preset page size of the catalog trigger).
const MAX_SEEN = 500;

interface TriggerSpec {
	method: IHttpRequestMethods;
	path: string;
	qs: IDataObject;
	descending: boolean;
	filters: { param: string; qsKey: string }[];
}

// The poll call of each catalog trigger (`pollFallback`): operation, fixed query, sort and filters.
const TRIGGERS: Record<string, TriggerSpec> = {
	newTask: {
		method: 'GET',
		path: '/tasks',
		qs: {
			scope: 'project',
			'archived[eq]': false,
			limit: 50,
			sort: '-createdAt',
			expand: 'project,status,list,assignees,labels,customFields',
		},
		descending: true,
		filters: [
			{
				param: 'project',
				qsKey: 'projectId[eq]',
			},
		],
	},
	completedTask: {
		method: 'GET',
		path: '/tasks',
		qs: {
			scope: 'project',
			'completed[eq]': true,
			'completedAt[gt]': '1970-01-01T00:00:00.000Z',
			limit: 50,
			sort: '-completedAt',
			expand: 'project,status,list,assignees,labels,customFields',
		},
		descending: true,
		filters: [
			{
				param: 'project',
				qsKey: 'projectId[eq]',
			},
		],
	},
	newProject: {
		method: 'GET',
		path: '/projects',
		qs: {
			'archived[eq]': false,
			limit: 50,
			sort: '-createdAt',
		},
		descending: true,
		filters: [],
	},
};

interface Row {
	id: string;
	name?: string;
	project?: { name?: string };
}

// Dropdown options of a choiceSource entry (one page: the preset limit).
async function loadChoices(context: ILoadOptionsFunctions, path: string, qs: IDataObject, withProject: boolean): Promise<INodePropertyOptions[]> {
	const response = (await context.helpers.httpRequestWithAuthentication.call(context, credentialOf(context), {
		method: 'GET',
		url: `${BASE_URL}${path}`,
		qs,
		headers: { 'X-API-Version': '3' },
		json: true,
	})) as { data?: Row[] };
	return (response.data ?? [])
		.map((row) => ({ name: withProject && row.project?.name ? `${row.project.name} › ${row.name}` : (row.name ?? row.id), value: row.id }))
		.sort((a, b) => a.name.localeCompare(b.name));
}

export class NiftyTrigger implements INodeType {
	description: INodeTypeDescription = {
		displayName: 'Nifty Trigger',
		name: 'niftyTrigger',
		icon: 'file:nifty.svg',
		group: [
			'trigger',
		],
		version: 1,
		subtitle: '={{ $parameter["event"] }}',
		description: 'Starts the workflow when something happens in Nifty (polls for changes)',
		defaults: {
			name: 'Nifty Trigger',
		},
		polling: true,
		inputs: [],
		outputs: [NodeConnectionTypes.Main],
		credentials: [
			{
				name: 'niftyOAuth2Api',
				required: true,
				displayOptions: {
					show: {
						authentication: [
							'oAuth2',
						],
					},
				},
			},
			{
				name: 'niftyApi',
				required: true,
				displayOptions: {
					show: {
						authentication: [
							'apiKey',
						],
					},
				},
			},
		],
		properties: [
			{
				displayName: 'Authentication',
				name: 'authentication',
				type: 'options',
				options: [
					{
						name: 'API Key',
						value: 'apiKey',
					},
					{
						name: 'OAuth2',
						value: 'oAuth2',
					},
				],
				default: 'apiKey',
			},
			{
				displayName: 'Event',
				name: 'event',
				type: 'options',
				noDataExpression: true,
				default: 'newTask',
				options: [
					{
						name: 'New Task',
						value: 'newTask',
						description: 'Triggers when a new task (or subtask) is created in Nifty, optionally only in one project',
					},
					{
						name: 'Task Completed',
						value: 'completedTask',
						description: 'Triggers when a task is marked complete in Nifty, optionally only in one project',
					},
					{
						name: 'New Project',
						value: 'newProject',
						description: 'Triggers when a new project is created in the Nifty workspace',
					},
				],
			},
			{
				displayName: 'Project Name or ID',
				description: 'Only trigger for tasks in this project. Leave empty for every project you can access. Choose from the list, or specify an ID using an <a href="https://docs.n8n.io/code/expressions/">expression</a>.',
				name: 'project',
				type: 'options',
				default: '',
				typeOptions: {
					loadOptionsMethod: 'getProjectChoices',
				},
				displayOptions: {
					show: {
						event: [
							'newTask',
							'completedTask',
						],
					},
				},
			},
		],
	};

	methods = {
		loadOptions: {
			async getProjectChoices(this: ILoadOptionsFunctions): Promise<INodePropertyOptions[]> {
				return await loadChoices(this, '/projects', {
					'archived[eq]': false,
					limit: 200,
				}, false);
			},
		},
	};

	async poll(this: IPollFunctions): Promise<INodeExecutionData[][] | null> {
		const event = this.getNodeParameter('event') as string;
		const spec = TRIGGERS[event];
		const qs: IDataObject = { ...spec.qs };
		for (const filter of spec.filters) {
			const value = this.getNodeParameter(filter.param, '') as string;
			if (value) qs[filter.qsKey] = value;
		}
		const manual = this.getMode() === 'manual';
		// Static data is not persisted in a manual run, so the test run neither reads nor writes it.
		const staticData = this.getWorkflowStaticData('node') as { seen?: Record<string, string[]> };
		// Keyed by event AND filter: a changed filter finds no entry and re-seeds silently instead of flooding old items.
		const key = `${event}:${JSON.stringify(Object.entries(qs).sort(([x], [y]) => (x < y ? -1 : x > y ? 1 : 0)))}`;
		const previous = staticData.seen?.[key];

		const response = (await this.helpers.httpRequestWithAuthentication.call(this, credentialOf(this), {
			method: spec.method,
			url: `${BASE_URL}${spec.path}`,
			qs,
			headers: { 'X-API-Version': '3' },
			json: true,
		})) as { data?: IDataObject[] };
		const rows = response.data ?? [];

		// Manual test run: show the latest item, as n8n triggers do.
		if (manual) return rows.length ? [this.helpers.returnJsonArray(rows.slice(0, 1))] : null;

		const ids = rows.map((row) => String(row.id));
		// Only the current key is kept (other filters are dropped) and the object is reassigned, so n8n persists it and it cannot grow.
		staticData.seen = { [key]: [...ids, ...(previous ?? []).filter((id) => !ids.includes(id))].slice(0, MAX_SEEN) };
		// First scheduled run: remember what is there, deliver nothing.
		if (previous === undefined) return null;

		const fresh = rows.filter((row) => !previous.includes(String(row.id)));
		if (!fresh.length) return null;
		// Deliver oldest first.
		return [this.helpers.returnJsonArray(spec.descending ? fresh.reverse() : fresh)];
	}
}
